  plot(el,{series:[{name:'2Y',color:C.cyan,pts:mk(2)},{name:'10Y',color:C.p,pts:mk(10)},{name:'30Y',color:C.pink,pts:mk(30),width:2.6}],xFmt:v=>v+'%',xTip:v=>'到期收益率 '+v+'%',yFmt:v=>v.toFixed(0),tipFmt:v=>v.toFixed(1),xLabel:'到期收益率',yLabel:'价格（面值 100）',hlines:[{y:100,label:'收益率 = 票息时，价格 = 100',color:C.gray}],vlines:[{x:4,label:'4%',color:C.gray}]});
