'use strict';
const AUTH_CONFIG=JSON.parse(document.getElementById('supabase-config').textContent);
const authState={client:null,user:null,ready:false,answersReady:false,error:'',generation:0,recovery:/type=recovery/.test(location.hash),returnLesson:'',signupEmail:''};
let accountStorageKey='ziyao-investment-learning-v1';

function accountRoute(tab='login',lesson=''){
 return '#/account?tab='+tab+(byId[lesson]?'&return='+encodeURIComponent(lesson):'');
}
function requestedLesson(query){return byId[query.get('return')]?query.get('return'):'';}
function authErrorMessage(error){
 const code=error?.code||'',message=String(error?.message||'');
 if(code==='invalid_credentials')return '邮箱或密码不正确，请检查后重试。';
 if(code==='email_not_confirmed')return '请先打开注册确认邮件，验证邮箱后再登录。';
 if(/rate_limit|over_email_send_rate_limit|over_request_rate_limit/.test(code))return '操作过于频繁，请稍后再试。';
 if(code==='weak_password'||/password.*(weak|short)/i.test(message))return '密码强度不足，请使用更长且不易猜测的密码。';
 if(code==='signup_disabled')return '当前暂未开放新账号注册，请稍后再试。';
 if(code==='email_address_invalid')return '请填写有效的邮箱地址。';
 if(code==='email_address_not_authorized'||/email.*(send|sending)/i.test(message))return '确认邮件暂时无法发送，请稍后再试或联系站点管理员。';
 if(/fetch|network|timeout/i.test(message))return '网络连接失败，请检查网络后重试。';
 return '账号操作暂未完成，请稍后重试。';
}
function loadAccountState(key){
 let result;
 try{result=cleanState(JSON.parse(localStorage.getItem(key)||'null'));}catch{result=cleanState(null);}
 result.answers={};
 return result;
}
function authReturnUrl(recovery=false){
 const u=new URL(AUTH_CONFIG.siteUrl);
 u.searchParams.set('auth_callback',recovery?'recovery':'confirm');
 return u.href;
}
function rememberReturn(lesson){
 if(byId[lesson]){authState.returnLesson=lesson;try{sessionStorage.setItem('ziyao-auth-return',lesson);}catch{}}
}
function consumeReturn(){
 let id=authState.returnLesson;
 try{id=sessionStorage.getItem('ziyao-auth-return')||id;sessionStorage.removeItem('ziyao-auth-return');}catch{}
 authState.returnLesson='';
 return byId[id]?id:'';
}
function renderSignupConfirmation(lesson){
 return pageHead('请查看邮箱，完成注册','完成邮箱验证后，请返回本站登录，即可开始答题。','CHECK YOUR EMAIL')+`<section class="panel auth-card auth-confirm-card"><div class="auth-confirm-icon" aria-hidden="true">${icon('check')}</div><h2>注册申请已提交</h2><p role="status">${authState.signupEmail?`请前往 <strong class="auth-email">${esc(authState.signupEmail)}</strong> 查看注册确认邮件。`:'请查看注册时填写的邮箱，找到注册确认邮件。'}</p><ol class="auth-steps"><li><strong>查看邮箱</strong><span>打开注册确认邮件，收件箱没有时也请检查垃圾邮件。</span></li><li><strong>完成邮箱验证</strong><span>点击邮件中的确认链接，完成注册验证。</span></li><li><strong>返回登录</strong><span>使用注册时的邮箱和密码登录，再回到课程答题。</span></li></ol><a class="btn primary auth-submit" href="${accountRoute('login',lesson)}&from=signup">已完成邮箱验证，去登录</a><p class="small muted">如果该邮箱已经注册并完成验证，可以直接登录。</p><div class="auth-confirm-links"><a class="text-link" href="${accountRoute('register',lesson)}">更换邮箱重新注册</a><a class="text-link" href="${lesson?'#/lesson/'+lesson:'#/courses'}">继续阅读课程</a></div></section>`;
}
function renderAccount(query){
 const lesson=requestedLesson(query);if(lesson)rememberReturn(lesson);
 const tab=['login','register','reset'].includes(query.get('tab'))?query.get('tab'):'login';
 if(!authState.ready)return pageHead('连接你的学习账号','正在检查登录状态。','YOUR LEARNING ACCOUNT')+'<section class="panel auth-card"><p role="status">正在连接账号服务…</p></section>';
 if(!authState.client)return pageHead('学习账号暂时无法连接','课程、图表与资料仍可公开浏览，请稍后再尝试登录。','YOUR LEARNING ACCOUNT')+'<section class="panel auth-card"><button class="btn primary" data-auth-retry>重新连接</button><a class="text-link" href="#/courses">继续阅读课程</a></section>';
 if(authState.user&&!authState.recovery)return pageHead('你的学习账号','答题结果保存在账号中，登录其他设备后可以继续查看。','YOUR LEARNING ACCOUNT')+`<section class="panel auth-card"><span class="pill green">已登录</span><h2 class="auth-title">${esc(authState.user.email||'学习者')}</h2><p>阅读进度、笔记和收藏保存在当前浏览器，并与其他账号分开；答题记录由账号保存。</p><div class="actions"><a class="btn primary" href="${lesson?'#/lesson/'+lesson:'#/records'}">${lesson?'返回本课答题':'查看学习记录'}</a><button class="btn ghost" data-auth-signout>退出登录</button></div><p class="small muted">退出登录后仍可公开阅读课程与资料。</p></section>`;
 if(query.get('tab')==='check-email')return renderSignupConfirmation(lesson);
 const recovery=authState.recovery&&authState.user;
 const title=recovery?'设置新密码':tab==='register'?'创建你的学习账号':tab==='reset'?'找回密码':'欢迎回来';
 const description=recovery?'填写新密码后，即可继续学习。':tab==='register'?'课程公开阅读。注册并登录后，可以答题、查看解析和保存答题记录。':tab==='reset'?'我们会向你的邮箱发送密码重置邮件。':'使用邮箱和密码登录，继续你的练习与复习。';
 return pageHead(title,description,'YOUR LEARNING ACCOUNT')+`<section class="panel auth-card">${recovery?'':`<div class="tabbar" aria-label="账号操作">${[['register','注册'],['login','登录']].map(([k,t])=>`<a class="btn ${tab===k?'primary':'ghost'}" href="${accountRoute(k,lesson)}" ${tab===k?'aria-current="page"':''}>${t}</a>`).join('')}</div>`}${!recovery&&tab==='login'&&query.get('from')==='signup'?'<p class="notice auth-login-notice">请先点击确认邮件中的链接完成验证，再使用注册时的邮箱和密码登录。</p>':''}<form id="account-form" data-mode="${recovery?'recovery':tab}" data-return="${lesson}">${recovery?'':`<label for="account-email">邮箱</label><input id="account-email" type="email" name="email" autocomplete="email" placeholder="你的邮箱地址" value="${tab==='login'?esc(authState.signupEmail):''}" maxlength="254" required>`}${tab==='reset'&&!recovery?'':`<label for="account-password">${recovery?'新密码':'密码'}</label><input id="account-password" name="password" type="password" autocomplete="${tab==='login'&&!recovery?'current-password':'new-password'}" ${tab==='login'&&!recovery?'':'minlength="8"'} maxlength="128" placeholder="${tab==='login'&&!recovery?'输入密码':'至少 8 位，建议混合字母与数字'}" required>${tab==='register'||recovery?'<label for="account-confirm">再次输入密码</label><input id="account-confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required>':''}`}<p id="account-message" class="auth-message" role="status" aria-live="polite"></p><button type="submit" class="btn primary auth-submit">${recovery?'保存新密码':tab==='register'?'注册账号':tab==='reset'?'发送重置邮件':'登录'}</button></form>${!recovery&&tab==='login'?`<a class="text-link" href="${accountRoute('reset',lesson)}">忘记密码</a>`:''}${!recovery&&tab==='reset'?`<a class="text-link" href="${accountRoute('login',lesson)}">返回登录</a>`:''}${tab==='register'&&!recovery?'<p class="small muted">注册后请查收确认邮件，验证邮箱后即可登录。邮箱和密码由账号服务处理，网站不会将密码写入学习备份。</p>':''}<a class="text-link" href="${lesson?'#/lesson/'+lesson:'#/courses'}">继续阅读课程</a></section>`;
}
function renderQuizContent(lesson){
 const a=authState.user&&authState.answersReady?state.answers[lesson.id]:null;
 const question=`<h3>${esc(lesson.title)}</h3><p id="quiz-question-${lesson.id}">${esc(lesson.quiz.question)}</p>`;
 if(!authState.user)return question+`<ol class="quiz-preview">${lesson.quiz.options.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="quiz-login"><h3>登录后开始答题</h3><p>注册并登录后提交答案，查看解析。答题结果会保存到你的账号。</p><div class="actions"><a class="btn primary" href="${accountRoute('register',lesson.id)}">注册账号</a><a class="btn ghost" href="${accountRoute('login',lesson.id)}">已有账号，登录</a></div></div>`;
 if(!authState.answersReady)return question+'<p class="notice" role="status">正在读取你的答题记录…</p>';
 return question+`<form id="quiz-form-${lesson.id}" data-quiz data-lesson="${lesson.id}" aria-labelledby="quiz-question-${lesson.id}">${lesson.quiz.options.map((option,i)=>`<label class="quiz-option ${a?(i===a.answerIndex?'correct':a.choice===i?'incorrect':''):''}"><input type="radio" name="answer" value="${i}" ${a?.choice===i?'checked':''} required><span>${esc(option)}</span></label>`).join('')}<div class="quiz-actions"><button type="submit" class="btn primary">${a?'重新检验':'提交答案'}</button><span class="small muted">提交后显示解析，并保存到账号</span></div></form><div id="quiz-feedback-${lesson.id}" class="quiz-feedback" ${a?'':'hidden'} role="status">${a?`<strong class="${a.correct?'positive':'amber'}">${a.correct?'回答正确':'再检查一次'}</strong><br>${esc(a.explanation)}${a.correct?'':'<br><span class="small">本题已加入待复习；答对后会自动移出。</span>'}`:''}</div>${authState.error?'<p class="small muted">'+esc(authState.error)+'</p>':''}`;
}
async function refreshAccountAnswers(userId,generation){
 const {data,error}=await authState.client.from('academy_answers').select('lesson_id,choice,is_correct,answered_at,academy_quiz_keys(answer_index,explanation)');
 if(generation!==authState.generation||authState.user?.id!==userId)return;
 state.answers={};
 if(error)authState.error='暂时无法读取已有答题记录。你可以稍后刷新重试。';
 else for(const row of data||[]){const key=row.academy_quiz_keys;if(byId[row.lesson_id]&&key&&Number.isInteger(row.choice))state.answers[row.lesson_id]={choice:row.choice,correct:row.is_correct===true,at:row.answered_at,answerIndex:key.answer_index,explanation:key.explanation};}
 authState.answersReady=true;persist();navigateRender(true);
}
async function applyAuthSession(session,event=''){
 const generation=++authState.generation;
 let user=null;
 if(session){const result=await authState.client.auth.getUser();if(generation!==authState.generation)return;if(!result.error&&!result.data.user?.is_anonymous)user=result.data.user;}
 const previous=authState.user?.id||null;
 authState.ready=true;authState.user=user;authState.error='';
 if(event==='PASSWORD_RECOVERY')authState.recovery=true;
 if(!user)authState.recovery=false;
 if(previous===(user?.id||null)&&authState.answersReady){
  if(user&&authState.recovery){location.hash='#/account?tab=recovery';navigateRender(true);}
  else updateShell();
  return;
 }
 accountStorageKey=user?'ziyao-investment-learning-v1:'+user.id:'ziyao-investment-learning-v1';
 state=loadAccountState(accountStorageKey);authState.answersReady=!user;
 if(user&&authState.recovery)location.hash='#/account?tab=recovery';
 else if(user&&(location.hash.startsWith('#/account')||new URLSearchParams(location.search).has('auth_callback'))){const id=consumeReturn();history.replaceState(null,'',location.pathname+(id?'#/lesson/'+id+'?section=quiz':'#/records'));}
 navigateRender(true);
 if(user)await refreshAccountAnswers(user.id,generation);
}
async function initializeAuth(){
 if(authState.client)return;
 try{
  if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(AUTH_CONFIG.url||'')||!AUTH_CONFIG.publishableKey)throw new Error('configuration');
  authState.client=window.supabase.createClient(AUTH_CONFIG.url,AUTH_CONFIG.publishableKey,{auth:{storageKey:'ziyao-supabase-auth',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'implicit'}});
  authState.client.auth.onAuthStateChange((event,session)=>{setTimeout(()=>applyAuthSession(session,event).catch(()=>{authState.ready=true;authState.error='暂时无法确认登录状态，请重新登录。';updateShell();}),0);});
  const {data,error}=await authState.client.auth.getSession();if(error)throw error;
  await applyAuthSession(data.session);
 }catch{authState.ready=true;authState.answersReady=true;authState.error='账号服务暂时无法连接，请稍后再试。';updateShell();if(location.hash.startsWith('#/account'))navigateRender(true);}
}
async function submitQuiz(form){
 const id=form.dataset.lesson,lesson=byId[id];if(!lesson)return;
 if(!authState.user||authState.user.is_anonymous){rememberReturn(id);location.hash=accountRoute('login',id);return;}
 const selected=form.querySelector('input:checked');if(!selected){toast('请先选择一个答案。');return;}
 const button=form.querySelector('button'),userId=authState.user.id,generation=authState.generation;
 button.disabled=true;button.textContent='正在保存…';
 try{
  const {data,error}=await authState.client.rpc('academy_submit_answer',{p_lesson_id:id,p_choice:Number(selected.value)});
  if(error)throw error;
  if(generation!==authState.generation||authState.user?.id!==userId)return;
  if(!data||data.lesson_id!==id||typeof data.correct!=='boolean'||!Number.isInteger(data.answerIndex))throw new Error('response');
  state.answers[id]={choice:data.choice,correct:data.correct,at:data.at,answerIndex:data.answerIndex,explanation:data.explanation};persist();
  if(form.isConnected){const section=form.closest('[data-quiz-section]')||$('#quiz-section');if(section)section.innerHTML=renderQuizContent(lesson);}
 }catch{if(form.isConnected){const section=form.closest('[data-quiz-section]')||$('#quiz-section');const feedback=section?.querySelector('.quiz-feedback');if(!feedback)return;feedback.hidden=false;feedback.textContent='答案暂未保存，请检查网络或重新登录后再试。';}}
 finally{if(button.isConnected){button.disabled=false;button.textContent='提交答案';}}
}
document.addEventListener('submit',async event=>{
 const form=event.target;if(form.id!=='account-form')return;event.preventDefault();
 const mode=form.dataset.mode,message=$('#account-message'),button=form.querySelector('button[type=submit]');
 const email=$('#account-email')?.value.trim(),password=$('#account-password')?.value,confirmation=$('#account-confirm')?.value;
 if((mode==='register'||mode==='recovery')&&password!==confirmation){message.textContent='两次输入的密码不一致。';return;}
 if(!authState.client){message.textContent='账号服务暂时无法连接，请稍后重试。';return;}
 rememberReturn(form.dataset.return);button.disabled=true;message.textContent='正在处理…';
 try{
  let result;
  if(mode==='register')result=await authState.client.auth.signUp({email,password,options:{emailRedirectTo:authReturnUrl()}});
  else if(mode==='reset')result=await authState.client.auth.resetPasswordForEmail(email,{redirectTo:authReturnUrl(true)});
  else if(mode==='recovery')result=await authState.client.auth.updateUser({password});
  else result=await authState.client.auth.signInWithPassword({email,password});
  if(result.error)throw result.error;
  if(mode==='register'&&!result.data.session){authState.signupEmail=email;form.querySelectorAll('input[type=password]').forEach(x=>x.value='');location.hash=accountRoute('check-email',form.dataset.return);}
  else if(mode==='reset')message.textContent='如该邮箱已注册，你会收到重置邮件。请打开邮件中的链接设置新密码。';
  else if(mode==='recovery'){authState.recovery=false;toast('新密码已保存。');location.hash='#/records';navigateRender();}
  else if(mode==='login'){message.textContent='登录成功，正在返回课程…';await applyAuthSession(result.data.session,'SIGNED_IN');}
 }catch(error){if(message.isConnected)message.textContent=authErrorMessage(error);}
 finally{if(button.isConnected)button.disabled=false;}
});
document.addEventListener('click',async event=>{
 const button=event.target.closest('button');if(!button)return;
 if(button.hasAttribute('data-auth-retry')){authState.client=null;authState.ready=false;navigateRender(true);initializeAuth();}
 if(button.hasAttribute('data-auth-signout')&&authState.client){button.disabled=true;const {error}=await authState.client.auth.signOut();if(error){button.disabled=false;toast('暂时无法退出，请检查网络后重试。');}else {await applyAuthSession(null);toast('已退出登录。');}}
});

