function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;}
let storageOK=true;
function cleanState(x){
 const o={version:1,completed:{},mastered:{},answers:{},notes:{},bookmarks:[],lastLesson:'economic-map',visits:{}};
 if(!x||typeof x!=='object'||Array.isArray(x))return o;
 for(const id of Object.keys(byId)){
  if(x.completed?.[id]===true)o.completed[id]=true;
  const n=x.notes?.[id];if(n&&typeof n.text==='string'&&n.text.trim())o.notes[id]={text:n.text.slice(0,50000),at:typeof n.at==='string'?n.at:''};
 }
 for(const [key,value] of Object.entries(x.mastered||{}))if(value===true&&/^[a-z0-9-]+:\d+$/.test(key))o.mastered[key]=true;
 o.bookmarks=Array.isArray(x.bookmarks)?[...new Set(x.bookmarks.filter(id=>byId[id]))]:[];
 if(byId[x.lastLesson])o.lastLesson=x.lastLesson;
 if(x.visits&&typeof x.visits==='object')for(const [date,count] of Object.entries(x.visits))if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(count)&&count>=0)o.visits[date]=Math.min(9999,count);
 return o;
}
let state;try{state=cleanState(JSON.parse(localStorage.getItem(accountStorageKey)||'null'));localStorage.setItem(accountStorageKey,JSON.stringify({...state,answers:{}}));}catch{storageOK=false;state=cleanState(null);}
function persist(){try{localStorage.setItem(accountStorageKey,JSON.stringify({...state,answers:{}}));storageOK=true;}catch{storageOK=false;}updateShell();}
