function resourceInline(id){const r=resById[id];if(!r)return '';return `<div class="source-inline"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ${icon('link')}</a><small>${esc(r.provider)} · ${esc(r.language)} · ${isVideo(r)?'视频/课程':'官方资料'}</small>${relatedLinks(r)}<p>${esc(r.watch_task||r.why||'结合本课概念，检查资料的日期与定义。')}</p></div>`;}
