function knowledgeSVG(){const coords={macro:[30,35],bonds:[285,35],dollar:[540,35],policy:[795,35],tech:[30,185],industry:[285,185],history:[540,185],trend:[795,185],indicators:[30,335],options:[285,335],strategies:[540,335],risk:[795,335]};return `<svg class="knowledge-svg" viewBox="0 0 1040 465" role="img" aria-labelledby="knowledge-title"><title id="knowledge-title">12 个模块的建议前置依赖。每个节点可打开课程，具体前置关系在每节课标注。</title><defs><marker id="dep-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="m0 0 7 3.5L0 7Z" fill="#6c4f86"/></marker></defs>${moduleEdges.map(([a,b])=>{const [x,y]=coords[a],[xx,yy]=coords[b];if(y===yy)return `<path d="M${x+210} ${y+38}H${xx-7}" fill="none" stroke="#684c80" stroke-width="1.3" marker-end="url(#dep-arrow)"/>`;return `<path d="M${x+105} ${y+77} C${x+105} ${y+116} ${xx+105} ${yy-35} ${xx+105} ${yy-7}" fill="none" stroke="#48334f" stroke-width="1.1" marker-end="url(#dep-arrow)"/>`;}).join('')}${modules.map(m=>{const[x,y]=coords[m.id],p=progress(m.id);return `<a href="#/courses?module=${m.id}" aria-label="${esc(m.title)}，${p.count}/${p.total}节已完成"><rect x="${x}" y="${y}" width="210" height="77" rx="11" fill="#211b2c" stroke="#594065"/><text x="${x+16}" y="${y+30}" fill="#e2d5ef" font-size="16">${esc(m.title)}</text><text x="${x+16}" y="${y+56}" fill="#9e8caf" font-size="12">${esc(m.phase)} · ${p.count}/${p.total} 节</text></a>`;}).join('')}</svg>`;}
function renderMap(query){const key=scenarios[query.get('scenario')]?query.get('scenario'):'inflation',s=scenarios[key];return pageHead('知识之间，有一条传导链。','用条件推演连接资产；用前置关系安排学习。图中的可能方向都需要证据确认。','CONNECT THE DOTS')+`<div class="map-scenarios">${Object.entries(scenarios).map(([k,v])=>`<button class="scenario-choice" data-scenario="${k}" aria-pressed="${key===k}"><b>${v.title}</b><small>${v.desc}</small></button>`).join('')}</div><section class="panel pad"><div class="section-head"><h2>${s.title}：一条条件路径</h2><span class="badge">情景推演 · 非实时判断</span></div><p class="small muted">${s.condition}</p><div class="chain">${s.chain.map((x,i)=>`<div class="chain-item"><span>${x}</span>${i<3?'<i aria-hidden="true">›</i>':''}</div>`).join('')}</div></section><div class="transmission-grid section">${s.tiles.map(([t,d,desc,id])=>`<section class="panel transmission-tile"><h3>${t}</h3><div class="direction">${d}</div><p>${desc}</p><a class="text-link" href="#/lesson/${id}">回到相关课程</a></section>`).join('')}</div><section class="section panel"><div class="pad"><h2>建议学习依赖图</h2><p class="small muted" style="margin-top:7px">连线表示知识依赖，节点可打开模块；每节课另列具体前置与后续知识。</p></div><div class="map-wrap">${knowledgeSVG()}</div><div class="dependency-detail"><h3>一个完整闭环</h3><p>宏观数据与政策预期 → 收益率曲线、实际利率与美元 → 行业收入和估值 → 技术与事件 → 期权结构 → 仓位、压力测试与复盘。</p><a href="#/lesson/capstone" class="text-link">查看毕业作业</a></div></section>`;}
const historyItems=[['1965—1982','大通胀与政策可信度','history-1970','区分供给、需求与政策的叠加，不把一轮油价冲击当成全部解释。'],['2000 前后','技术革命与估值泡沫','history-2000','技术长期方向可以正确，买入估值、竞争与稀释仍决定投资回报。'],['2007—2009','杠杆与信用链断裂','history-2008','追踪抵押品、短期融资、信用损失与去杠杆如何互相放大。'],['2020','现金冲击与政策修复','history-2020','按阶段研究资金需求、经济停摆、政策与需求迁移。'],['2022','股债同跌与共同久期风险','history-2022','当通胀与实际利率主导，传统资产类别可能同时承压。'],['2023','银行的期限与流动性错配','history-2023','会计分类不能替代流动性准备，未实现损失也有经济意义。']];
function renderHistory(){return pageHead('历史，是框架的压力测试。','先还原当时可得的信息，再解释机制。避免用结局反推一切都可以事先知道。','LEARN FROM MARKET HISTORY')+`<div class="notice">这些案例侧重机制与研究方法，未伪造历史收益图。要做资产回报比较，请使用同一口径、同一日期区间的原始数据。</div><div class="history-list section">${historyItems.map(([year,title,id,desc])=>`<article class="panel history-card"><div class="history-year">${year}</div><div><h2>${title}</h2><p>${desc}</p><span class="pill">${esc(byId[id].chain.slice(0,3).join(' · '))}</span><div class="actions"><a href="#/lesson/${id}" class="btn ghost">进入复盘课程</a><a class="text-link" href="#/lab/bond">用利率实验验证</a></div></div></article>`).join('')}</div><section class="panel pad section"><h2>统一复盘模板</h2><p class="subtitle">事件时间线 → 当时已知信息 → 宏观与信用驱动 → 跨资产反应 → 政策与约束 → 哪些结论可迁移 → 哪些条件已改变。</p><a href="#/lesson/capstone" class="text-link">在综合作业中练习</a></section>`;}
function relatedLinks(r){return r.related_links?.length?`<div class="actions" style="margin-top:10px">${r.related_links.map(x=>`<a class="text-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer" style="font-size:.8rem">${esc(x.title)}</a>`).join('')}</div>`:'';}
