let courseChartsObserver=null;
function rootUrl(){return new URL(location.pathname.includes('/modules/')?'../':'./',location.href);}
function moduleUrl(id,point){
 const q=Number.isInteger(point)?'?point='+point:'';
 if(location.protocol==='file:')return '#/module/'+id+q;
 const u=new URL('modules/'+id+'.html',rootUrl());if(q)u.hash='/module/'+id+q;return u.pathname+u.hash;
}
function homeUrl(hash='#/home'){return location.protocol==='file:'?hash:new URL('index.html'+hash,rootUrl()).pathname+hash;}
