 macro:[1,2,5,0],fed:[3,1,2],inflation:[0,1,1,6],bonds:[0,1,4,0],us02y:[1,2],
 us10y:[5,1,0],us30y:[4,1,1],tlt:[1,2,0],dxy:[3,0,1,4],cds:[2,4],politics:[0,0,1],
 tech:[2,1,1],sectors:[0,5,5],btc:[0,3,4,0],options:[3,0,1,2],strategies:[6,1,0,4],
 history:[5,0,0],framework:[0,1,4],'ta-basics':[3,4,2],'ta-patterns':[3,2],'ta-trend':[1,3,3],
 'ta-momentum':[3,3],'ta-vol':[0,2],'ta-volume':[3,2],'ta-advanced':[1,2],
