function pointResources(m,pointIndex){
 const media=m.media.filter(([kind])=>['yt','bili','pod'].includes(kind));
 const items=media.flatMap(([kind,title,description,query],i)=>{
  if(pointResourceIndices[m.id][i]!==pointIndex)return [];
  const prefix=kind==='bili'?'https://search.bilibili.com/all?keyword=':'https://www.youtube.com/results?search_query=';
  const url=prefix+encodeURIComponent(query);
  return [`<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)}</a><small>${esc(description)}</small></li>`];
 });
 return items.length?`<details class="topic-sources"><summary>同主题的频道与检索入口</summary><ul>${items.join('')}</ul></details>`:'';
}
function moduleResources(m){const media=m.media.filter(([type])=>['book','web'].includes(type));if(!media.length)return '';return `<section class="reference-reading"><h2>延伸阅读与数据</h2>${media.map(([type,title,desc,url])=>`<div class="reading-resource"><span class="mtype t-${type}">${type==='book'?'书籍':'数据'}</span><div>${type==='web'&&url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)}</a>`:`<b>${esc(title)}</b>`}<p>${esc(desc)}</p></div></div>`).join('')}</section>`;}
function renderChapter(id){
 const m=chapterById[id];if(!m)return renderMissing();const p=mastery(m),ids=CHAPTER_LESSONS[id]||[],index=Ref.MODULES.indexOf(m),prev=Ref.MODULES[index-1],next=Ref.MODULES[index+1],st=Ref.STAGES.find(s=>s.id===m.stage);
 return `<div class="chapter-crumb"><a href="${homeUrl()}">学习路线</a><span>/</span><a href="${homeUrl('#/courses')}">${st.name}</a><span>/ ${m.code}</span></div><article class="module chapter-page" data-current-chapter="${id}"><header class="mod-head"><span class="mod-code">${m.code}</span><div><h1>${m.title}</h1><p class="mod-tag">${m.tag}</p></div><div class="mod-prog"><span class="chapter-mastered">${p.d} / ${p.n} 已掌握</span><div class="bar"><i style="width:${p.p}%"></i></div></div></header><div class="goal"><b>学习目标</b>${m.goal}</div><div class="bridge"><b class="lbl">与前文的结合</b>${m.bridge}${m.links.length?`<div class="chips">${m.links.map(chip).join('')}</div>`:''}</div><nav class="chapter-toc" aria-label="本章内容">${m.points.map((x,i)=>`<a href="#/module/${id}?point=${i}">${i+1}. ${x[0]}</a>`).join('')}<a href="#/module/${id}?section=practice">练习与自测</a></nav><div class="points">${m.points.map((point,i)=>{const key=id+':'+i,charts=CHART_PLACEMENTS[id]?.[i]||[],videos=POINT_VIDEOS[key]||[];return `<section class="pt ${videos.length||charts.length?'pt-wide':''}${state.mastered?.[key]?' done':''}" id="point-${id}-${i}"><div class="pt-head"><span class="pt-n">${String(i+1).padStart(2,'0')}</span><h2>${point[0]}</h2><label class="chk"><input type="checkbox" data-mastered="${key}" ${state.mastered?.[key]?'checked':''}>掌握</label></div><div class="pt-body">${point[1]}</div>${point[2]?.length?`<div class="chips"><span class="lk">关联知识</span>${point[2].map(chip).join('')}</div>`:''}${videos.map(videoBlock).join('')}${caseBlock(key)}${charts.map(chartBlock).join('')}${pointResources(m,i)}</section>`;}).join('')}</div>${ids.length?`<section class="chapter-deep"><h2>把机制讲透</h2><p class="muted">展开阅读算例、常见误区并记录笔记。全部练习与自测统一放在章末。</p>${ids.map(deeperReading).join('')}</section>`:''}${moduleResources(m)}<section class="chapter-practice" id="chapter-practice"><div class="practice-heading"><span class="mtype t-web">章末</span><h2>练习与自测</h2></div><section class="written-practice"><h3>动手练习</h3><ol>${m.practice.map(x=>`<li>${x}</li>`).join('')}</ol></section><div class="self-tests"><h3>情景自测</h3><p class="muted">${authState.user?'选择后提交，即时查看解析。答题结果保存到账号。':'题目可公开阅读。注册并登录后，可以提交答案、查看解析并保存记录。'}</p>${ids.map(lid=>`<section class="chapter-quiz" id="quiz-${lid}" data-quiz-section="${lid}">${renderQuizContent(byId[lid])}</section>`).join('')}</div></section></article><nav class="chapter-pager" aria-label="章节翻页">${prev?`<a class="btn ghost" href="${moduleUrl(prev.id)}">上一章 · ${prev.code} ${prev.short}</a>`:`<a class="btn ghost" href="${homeUrl()}">返回学习路线</a>`}${next?`<a class="btn primary" href="${moduleUrl(next.id)}">下一章 · ${next.code} ${next.short}</a>`:`<a class="btn primary" href="${homeUrl('#/records')}">查看学习记录</a>`}</nav>`;
}
const oldRenderRecords=renderRecords;
renderRecords=function(query){const n=Object.keys(state.mastered||{}).length;return `<div class="notice">已标记掌握 ${n} / 175 个知识点。下方保留 72 节精读的笔记、收藏及账号自测记录。</div>`+oldRenderRecords(query);};
function mountReferenceCharts(){
 courseChartsObserver?.disconnect();
 const mount=el=>{if(el.dataset.mounted)return;el.dataset.mounted='1';try{Ref.CHARTS[el.dataset.refChart].r(el);}catch(error){el.innerHTML='<p class="notice">图表暂未加载，请刷新重试。</p>';console.error(error);}};
 if('IntersectionObserver'in window){courseChartsObserver=new IntersectionObserver(entries=>{for(const en of entries)if(en.isIntersecting){courseChartsObserver.unobserve(en.target);mount(en.target);}},{rootMargin:'300px'});$$('[data-ref-chart]').forEach(el=>courseChartsObserver.observe(el));}else $$('[data-ref-chart]').forEach(mount);
}
navigateRender=function(keepScroll=false){
 const pos=window.scrollY;closeNav();const raw=(location.hash||'').replace(/^#\/?/,''),[path,qs]=raw.split('?');let [view,id]=path.split('/');const query=new URLSearchParams(qs||'');
 const oldModule=view.startsWith('m-')?view.slice(2):'';
 if(oldModule&&chapterById[oldModule]){location.replace(moduleUrl(oldModule));return;}
 const stage=Ref.STAGES.find(s=>view==='stage-'+s.id);
 if(stage)view='home';
 if(!view){id=document.body.dataset.module;view=id?'module':'home';}
 const legacyLesson=view==='lesson'&&byId[id]?id:null;
 if(legacyLesson){id=LESSON_CHAPTER[legacyLesson];view='module';state.lastLesson=legacyLesson;}
 let html;
 const renderers={home:()=>renderHome(),courses:()=>renderCourses(query),module:()=>renderChapter(id),map:()=>renderHome(),lab:()=>renderLab(id),history:()=>renderChapter('history'),resources:()=>pageHead('视频与原始资料','课程视频已放在对应知识点下方。点击目录进入章节，边学边看。')+renderDirectory(''),dictionary:()=>renderDictionary(),records:()=>renderRecords(query),settings:()=>renderSettings(),account:()=>renderAccount(query)};
 html=(renderers[view]||renderMissing)();disconnectCaptionPlayers();$('#main').innerHTML=html+footer();
 document.title=(view==='module'&&chapterById[id]?chapterById[id].title+' · ':'')+'投资 · 从宏观到技术';$('#breadcrumb').textContent=view==='module'&&chapterById[id]?chapterById[id].code+' '+chapterById[id].short:routeNames[view]||'学习路线';
 $$('[data-chapter-nav]').forEach(a=>{const active=a.dataset.chapterNav===(view==='module'?id:view==='history'?'history':'');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if($('#reference-graph'))renderGraph($('#reference-graph'));if(view==='dictionary')updateDictionary();if(view==='lab')updateLab();mountReferenceCharts();mountCaptionPlayers();updateShell();
 if(keepScroll)window.scrollTo(0,pos);else{window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
 let target=stage?$('#stage-'+stage.id):query.get('section')==='quiz'&&legacyLesson?$('#quiz-'+legacyLesson):query.get('section')==='practice'?$('#chapter-practice'):query.has('point')?$('#point-'+id+'-'+Number(query.get('point'))):legacyLesson?$('#reading-'+legacyLesson):null;
 if(target&&(!keepScroll||query.get('section')==='quiz'&&!authState.answersReady)){if(target.tagName==='DETAILS')target.open=true;requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));}
};
document.addEventListener('change',e=>{if(!e.target.matches('[data-mastered]'))return;state.mastered??={};const key=e.target.dataset.mastered;if(e.target.checked)state.mastered[key]=true;else delete state.mastered[key];e.target.closest('.pt').classList.toggle('done',e.target.checked);persist();});
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();window.scrollTo(0,0);}});
document.addEventListener('input',e=>{
 if(e.target.id==='chapter-search'){clearTimeout(window.chapterSearchTimer);const value=e.target.value;window.chapterSearchTimer=setTimeout(()=>{history.replaceState(null,'','#/courses'+(value?'?q='+encodeURIComponent(value):''));navigateRender(true);},180);}
 const id=e.target.dataset.readingNote;if(id&&byId[id]){if(e.target.value.trim())state.notes[id]={text:e.target.value.slice(0,50000),at:new Date().toISOString()};else delete state.notes[id];persist();$(`[data-note-status="${id}"]`).textContent=storageOK?'已自动保存到本机':'未能保存，请复制或导出笔记';}
});
$('#sidebar-search-form').addEventListener('submit',e=>{e.preventDefault();location.hash='#/courses?q='+encodeURIComponent($('#chapter-search').value);});
function importOriginalMastery(){
 try{
  const marker='investment-course:imported-original-progress';
  if(localStorage.getItem(marker))return;
  const original=JSON.parse(localStorage.getItem('macro-ta-course-progress-v1')||'[]');
  if(!Array.isArray(original)||!original.length)return;
  const saved=new Set(original);
  for(const m of Ref.MODULES)m.points.forEach((_,i)=>{if(saved.has(m.id+'-'+i))state.mastered[m.id+':'+i]=true;});
  localStorage.setItem(accountStorageKey,JSON.stringify({...state,answers:{}}));
  localStorage.setItem(marker,'1');
 }catch{/* Browsing remains available when storage is disabled. */}
}
